const spans = [
  { name: 'lb-route', ms: 2 },
  { name: 'gateway-auth', ms: 6 },
  { name: 'service-handler', ms: 4 },
  { name: 'pool-acquire', ms: 180 },
  { name: 'db-insert', ms: 12 },
  { name: 'provider-charge', ms: 140 },
  { name: 'serialize-response', ms: 3 },
];

// TODO 1: total = sum of every span's ms
const total = spans.reduce((acc, s) => acc + s.ms, 0);

// TODO 2: slowest = the span object with the largest ms
const slowest = spans.reduce((a, b) => (b.ms > a.ms ? b : a));

// TODO 3: pct = slowest.ms as an integer percentage of total
const pct = Math.round((slowest.ms / total) * 100);

console.log(`total=${total}ms critical=${slowest.name}(${slowest.ms}ms) share=${pct}%`);
